const db = require('better-sqlite3')('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));

for (const {name} of tables) {
  const cols = db.prepare('SELECT * FROM ' + name + ' LIMIT 0').columns().map(c => c.name);
  for (const col of cols) {
    try {
      const rows = db.prepare('SELECT * FROM ' + name + ' WHERE CAST(' + col + ' AS TEXT) LIKE ? OR CAST(' + col + ' AS TEXT) LIKE ?').all('%PROD-73FAB4%', '%Aurora Smart Desk Lamp%');
      if (rows.length > 0) {
        console.log('\n=== Table:', name, '===');
        for (const row of rows) {
          console.log(JSON.stringify(row, null, 2));
        }
      }
    } catch(e) {}
  }
}
"

